package com.example

import com.example.ExamQuestionHelper.QSpec

object DancingLiveExamOriginTradBank1 {
    private const val T = "නර්තනයේ මූලාරම්භය, ඓතිහාසික විකාශනය හා සම්ප්‍රදායන්"
    private fun q(stem: String, c: String, d1: String, d2: String, d3: String, exp: String) =
        QSpec(T, stem, c, listOf(d1, d2, d3), exp)

    fun questions(): List<QSpec> = listOf(
        q("ශ්‍රී ලංකාවේ ප්‍රධාන සම්භාව්‍ය නර්තන සම්ප්‍රදායන් තුන මොනවාද?", "උඩරට, පහතරට සහ සබරගමු", "උඩරට, භරත සහ කථක්", "පහතරට, කථකලි සහ ඔඩිසි", "සබරගමු, මණිපුරි සහ කුචිපුඩි", "ලංකාවේ දේශීය නර්තන සම්ප්‍රදායන් තුන වන්නේ උඩරට, පහතරට සහ සබරගමුය."),
        q("ආදි මානවයා තුළ නර්තනය ආරම්භ වීමට බලපෑ ප්‍රධානම සාධකය කුමක්ද?", "සොබාදහමට බිය හා ගරුත්වය දැක්වීම", "වේදිකා නාට්‍ය ප්‍රදර්ශනය", "ලිඛිත කාව්‍ය ගායනය", "නූතන සංගීත තරග", "ස්වාභාවික බලවේගයන්ගෙන් ආරක්ෂාව පැතීම ආදි නර්තන අංගවලට මුල් විය."),
        q("බෞද්ධ සාහිත්‍යය අනුව ශ්‍රී ලංකාවේ නර්තන හා වාදන කලාව පිළිබඳ පැරණිතම තොරතුරු සඳහන් වන්නේ කුමන යුගයේද?", "විජය රජුගේ ආගමනය හා කුවේණි පුවත තුළින්", "කෝට්ටේ රාජධානි යුගයේදී පමණි", "සීතාවක යුගයේදී පමණි", "බ්‍රිතාන්‍ය පාලන යුගයේදී පමණි", "විජය කුමරු ලංකාවට පැමිණි දා යක්ෂ ගෝත්‍රිකයන් තූර්ය නාද සහිත නැටුම් පැවැත්වූ බව මහාවංශයේ සඳහන් වේ."),
        q("මහාවංශයේ සඳහන් වන පරිදි බුදුන් වහන්සේගේ ධාතු තැන්පත් කිරීමේදී හා උත්සවවලදී පැවැත්වූ නැටුම් සම්ප්‍රදාය හැඳින්වෙන්නේ කෙසේද?", "දේව හා බෝධි පූජා නර්තන", "කෝලම් හා සොකරි නැටුම්", "බැලේ නර්තන", "කථක් නර්තන", "අනුරාධපුර යුගයේ සිටම ශ්‍රී මහා බෝධිය හා රුවන්වැලිසෑය වැනි පූජනීය ස්ථානවල තේවා නැටුම් පැවැත්විණි."),
        q("ශ්‍රී මහා බෝධීන් වහන්සේ වැඩමවීමත් සමඟ ලංකාවට පැමිණි ශිල්පීය කුල අතර නර්තනය හා වාදනයට සම්බන්ධ පිරිස් පිළිබඳව සඳහන් මූලාශ්‍රය කුමක්ද?", "මහාවංශය හා බෝධිවංශය", "සන්දේශ කාව්‍ය පමණි", "ජනකතා සංග්‍රහය පමණි", "දම්පියා අටුවා ගැටපදය පමණි", "බෝධි ආගමනයත් සමඟ විවිධ කලා ශිල්පී කුල මෙරටට පැමිණි බව ඓතිහාසික මූලාශ්‍ර දක්වයි."),
        q("දඹදෙණි යුගයේ රචිත 'කව්සිළුමිණ' වැනි ග්‍රන්ථවල නර්තනය පිළිබඳ තොරතුරු ඇතුළත් වන්නේ කුමන කාරණයක් ඇසුරෙන්ද?", "රාජ සභාවල රංගන හා අභිනය විස්තර ලෙස", "වෙස්මුහුණු කැපීමේ තාක්ෂණය ලෙස", "බටහිර නර්තන රීති ලෙස", "පහතරට සන්නි විස්තර ලෙස", "පැරණි සිංහල මහා කාව්‍යවල රාජ සභා නාට්‍යාංගනාවන්ගේ නර්තන රංගන වර්ණනා කර ඇත."),
        q("පොළොන්නරු යුගයේදී 'ශිව නටරාජ' වැනි ප්‍රතිමා නිර්මාණය වීමෙන් පිළිබිඹු වන සංස්කෘතික බලපෑම කුමක්ද?", "දකුණු ඉන්දීය හින්දු නර්තන හා කලා ආභාසය", "චීන ජන නර්තන ආභාසය", "පෘතුගීසි කපිරිඤ්ඤා ආභාසය", "ලන්දේසි සංගීත ආභාසය", "පොළොන්නරු යුගයේ හින්දු දේවාලවල පැවති නර්තන සම්ප්‍රදායන්ට භාරතීය ආභාසය ලැබිණි."),
        q("ගම්පොළ යුගයේ ඉදිකරන ලද ඇම්බැක්කේ දේවාලයේ ලී කැටයම් අතර බහුලව දක්නට ලැබෙන නර්තන දර්ශන මොනවාද?", "නළඟනන්, බෙර වාදකයන් සහ පන්තේරු නැට්ටුවන්", "කෝලම් හේවායන් සහ ජසයා", "සන්නි යකුන් දහඅට දෙනා", "මනමේ නාඩගම් චරිත", "ඇම්බැක්කේ දේවාලයේ ලී කුළුණු කැටයම් ලාංකේය මධ්‍යකාලීන නර්තන කලාවේ වැදගත් සාක්ෂියකි."),
        q("යාපහුව රාජධානි සමයට අයත් ගල් පඩිපෙළෙහි කැටයම් කර ඇති විශේෂ කලා අංගය කුමක්ද?", "නැටුම්කරුවන් හා තූර්ය වාදකයන්ගේ කැටයම්", "වෙස්මුහුණු පැළඳි චරිත කැටයම්", "සන්නි රෝග ලක්ෂණ කැටයම්", "නූතන වේදිකා රංග පසුබිම්", "යාපහුව ගල් කැටයම් අතර තාල තබන හා බෙර වයන නර්තන ශිල්පීන්ගේ රූප මැනවින් දිස්වේ."),
        q("කෝට්ටේ යුගයේ සන්දේශ කාව්‍යවල දේවාල නැටුම් ගැන වර්ණනා කිරීමේදී නිතර යොදා ඇති සංකල්පය කුමක්ද?", "දිගැසියන්ගේ රැඟුම් හා තූර්ය නාද පූජා", "වෙස්මුහුණු කැපීමේ මන්ත්‍ර", "බටහිර වාද්‍ය භාණ්ඩ වාදනය", "පන්සිල් සමාදන් වීම", "සැළලිහිණි හා පරෙවි වැනි සන්දේශ කාව්‍යවල කැලණිය හා තොටගමුව වැනි ස්ථානවල නැටුම් වර්ණනා වේ."),
        q("කැලණි විහාරයේ රංග ශාලාව හා දේවාල නළඟනන්ගේ රැඟුම් අලංකාර ලෙස වර්ණනා කර ඇති සන්දේශ කාව්‍යය කුමක්ද?", "සැළලිහිණි සන්දේශය", "සැවුල් සන්දේශය", "කහකුරුළු සන්දේශය", "දියසැවුල් සන්දේශය", "තොටගමුවේ ශ්‍රී රාහුල හිමියන්ගේ සැළලිහිණි සන්දේශයේ රංග නළඟනන් ගැන සවිස්තර කවි ඇත."),
        q("උඩරට නර්තන සම්ප්‍රදායේ ආරම්භක පුරාවෘත්තය ලෙස සැලකෙන ප්‍රධාන ශාන්තිකර්මය කුමක්ද?", "කොහොඹා කංකාරිය", "දහඅට සන්නිය", "ගම්මඩුව", "රට යකුම", "පඬුවස්දෙව් රජුගේ දිවි දෝෂය සුව කිරීමට පැවැත්වූ කොහොඹා කංකාරිය උඩරට නැටුමේ මූලාරම්භයයි."),
        q("මහනුවර යුගයේ රජවරුන් විසින් උඩරට නර්තන ශිල්පීන් හඳුන්වා දී ඔවුන්ට පවරන ලද ඉඩම් හඳුන්වනු ලබන්නේ කුමන නමකින්ද?", "නින්දගම් සහ රාජකාරි ඉඩම්", "පරවේණි අඳ ගොවි ඉඩම්", "සින්නක්කර නගර ඉඩම්", "බදු රහිත වතු යාය", "දළදා මාලිගාවේ හා සිව් මහා දේවාලවල තේවා රාජකාරි ඉටු කිරීම සඳහා කලාකරුවන්ට ගම්වර පිරිනැමිණි."),
        q("නුවර ඇසළ පෙරහැරට ශ්‍රී දළදා වහන්සේ වැඩමවීම එක් කර විධිමත් සංස්කෘතික මංගල්‍යයක් බවට පත් කළ රජතුමා කවුද?", "කීර්ති ශ්‍රී රාජසිංහ රජු", "විජයබාහු රජු", "පළමුවන පරාක්‍රමබාහු රජු", "දුටුගැමුණු රජු", "කීර්ති ශ්‍රී රාජසිංහ රජ සමයේ සරණංකර හිමියන්ගේ අනුශාසනා පරිදි දළදා පෙරහැර වත්මන් ස්වරූපයට සැකසිණි."),
        q("ලංකාවේ දේශීය නර්තන කලාව ශාස්ත්‍රීය අධ්‍යාපන පද්ධතියට ඇතුළත් කිරීමට පුරෝගාමී වූ විද්වතා කවුද?", "පණීභාරත මහතා", "මාර්ටින් වික්‍රමසිංහ මහතා", "මුනිදාස කුමාරතුංග මහතා", "ආනන්ද සමරකෝන් මහතා", "එස්. පණීභාරත මහතා දේශීය නර්තනය පාසල් හා විශ්වවිද්‍යාල විෂය මාලාවට ගෙන ඒමට මූලික විය."),
        q("නවීන වේදිකාව මත උඩරට නර්තනය මුද්‍රා නාට්‍ය ආකෘතියෙන් ලොවට ගෙන ගිය ප්‍රවීණ නර්තනවේදියා කවුද?", "චිත්‍රසේන මහතා", "එඩ්වඩ් ජයකොඩි මහතා", "වික්ටර් රත්නායක මහතා", "හෙන්රි ජයසේන මහතා", "චිත්‍රසේන සහ වජිරා යුවළ 'කරදිය' සහ 'නල දමයන්ති' වැනි මුද්‍රා නාට්‍ය නිර්මාණය කළහ."),
        q("පහතරට නර්තන සම්ප්‍රදාය ප්‍රධාන වශයෙන් ව්‍යාප්ත වී ඇති ශ්‍රී ලංකාවේ භූගෝලීය කලාපය කුමක්ද?", "දකුණු හා බස්නාහිර වෙරළබඩ ප්‍රදේශ", "උතුරු මැද වියළි කලාපය", "මධ්‍යම කඳුකර ප්‍රදේශ", "නැගෙනහිර මුහුදුබඩ කලාපය", "මාතර, බෙන්තර සහ රයිගම වැනි ගුරුකුල කේන්ද්‍ර කර ගනිමින් පහතරට නර්තනය වර්ධනය විය."),
        q("සබරගමු නර්තන සම්ප්‍රදාය කේන්ද්‍රගත වී ඇති ප්‍රධාන පළාත සහ නගරය කුමක්ද?", "සබරගමුව පළාතේ රත්නපුර ප්‍රදේශය", "මධ්‍යම පළාතේ මාතලේ ප්‍රදේශය", "දකුණු පළාතේ හම්බන්තොට ප්‍රදේශය", "වයඹ පළාතේ පුත්තලම ප්‍රදේශය", "රත්නපුර මහ සමන් දේවාලය ඇසුරෙන් සබරගමු නර්තන සම්ප්‍රදාය පෝෂණය වී ඇත."),
        q("උඩරට නර්තන සම්ප්‍රදාය ආරක්ෂා වී පැවති ප්‍රධාන රාජධානි ප්‍රදේශය කුමක්ද?", "මහනුවර ඇතුළු මධ්‍යම කඳුකරය", "රුහුණු රාජධානිය", "යාපනය රාජධානිය", "සීතාවක රාජධානිය", "සෙංකඩගල මහනුවර රාජධානිය උඩරට නර්තනයේ රාජකීය පෝෂණ කේන්ද්‍රස්ථානය විය."),
        q("පැරණි සිංහල රජවරුන් නර්තන හා සංගීත ශිල්පීන්ගේ කටයුතු පරිපාලනය කිරීමට පිහිටුවා තිබූ ආයතනය කුමක්ද?", "කවිකාර මඩුව", "මහ අධිකරණය", "රාජ්‍ය භාණ්ඩාගාරය", "සන්නස් ලේකම් කාර්යාලය", "රාජ සභාවේ ගායන, වාදන හා නර්තන ශිල්පීන් කවිකාර මඩුව යටතේ සංවිධානය විය."),
        q("කවිකාර මඩුවේදී රජු ඉදිරියේ ගායනා කරන ලද ප්‍රශස්ති හා වන්නම් රචනා වූයේ කුමන යුගයේදීද?", "මහනුවර යුගයේදී", "අනුරාධපුර යුගයේදී", "පොළොන්නරු යුගයේදී", "දඹදෙණි යුගයේදී", "ශ්‍රී වීර පරාක්‍රම නරේන්ද්‍රසිංහ රජුගේ කවිකාර මඩුවේදී වන්නම් කවි ප්‍රචලිත විය."),
        q("ශ්‍රී ලංකාවේ ජන නැටුම් ප්‍රධාන වශයෙන් කුමන ජන ජීවිත අංගයන් හා බැඳී පවතීද?", "ගොවිතැන, ජලය ගෙන ඒම හා එදිනෙදා ජීවනෝපායන්", "රාජ්‍ය සභා නීති පැනවීම", "විදේශීය රාජ්‍ය තාන්ත්‍රික සබඳතා", "යුද අභ්‍යාස සැලසුම් කිරීම", "ගැමි ජනතාවගේ ශ්‍රමය, සතුට හා විනෝදාස්වාදය ජන නැටුම්වලින් නිරූපණය වේ."),
        q("ගැමි කාන්තාවන් විසින් පිත්තල හෝ මැටි කළ භාවිත කරමින් ඉදිරිපත් කරන අලංකාර ජන නැටුම කුමක්ද?", "කළගෙඩි නැටුම", "ලී කෙළි නැටුම", "වඩිග පටුන", "පන්තේරු නැටුම", "දිය කෙළිය හා කළයකින් ජලය ගෙන යාමේ චලන අනුකරණය කරමින් කළගෙඩි නැටුම නටනු ලැබේ."),
        q("කුලු භාවිත කරමින් වී පෙළීමේ ක්‍රියාවලිය රිද්මයානුකූලව නිරූපණය කරන සාම්ප්‍රදායික ජන නැටුම කුමක්ද?", "කුලු නැටුම", "සවරම් නැටුම", "ගොයම් නැටුම", "තාලම් නැටුම", "කමතේ වී පිරිසිදු කිරීමේ ක්‍රියාව කුලු චලන මගින් කුලු නැටුමේදී නිරූපණය කෙරේ."),
        q("අත් රබන් හෝ බංකු රබාන වටා එක්වී කවි ගයමින් සිංහල අවුරුදු සමයේදී නටන ජන කලා අංගය කුමක්ද?", "රබන් නැටුම සහ රබන් ක්‍රීඩාව", "සළු පාලිය", "ගරා නැටුම", "හවඩි නැටුම", "අත් රබන් කරකවමින් නටන රබන් නැටුම ගැමි උත්සවවල ප්‍රීතිමත් අංගයකි."),
        q("දෙඅත්වල කුඩා ලී කැබලි දෙකක් රඳවා එකිනෙකාගේ ලීවල ගට්ටමින් නටන පිරිමි ජන නැටුම කුමක්ද?", "ලී කෙළි නැටුම", "පොල් කටු නැටුම", "චාමර නැටුම", "කස නැටුම", "රිද්මයානුකූලව ලී කෙළි ගසමින් රවුම් හා පෙළට සිට ඉදිරිපත් කරන ජන නැටුමකි."),
        q("ගොයම් කැපීමේ කාර්යය හා බැඳුණු කමත් භාෂාව හා කවි ඇසුරෙන් නටන ජන නැටුම කුමක්ද?", "ගොයම් නැටුම", "මල් නැටුම", "කළගෙඩි නැටුම", "රබන් නැටුම", "කැති හා දෑකැති චලන සංකේතවත් කරමින් ගොයම් කවි ගයමින් ගොයම් නැටුම නටනු ලැබේ."),
        q("පොල් කටු දෙකක් භාවිත කරමින් තාලයට ගටමින් ගැමි කාන්තාවන් හෝ පිරිමින් ඉදිරිපත් කරන ජන නැටුම කුමක්ද?", "පොල් කටු නැටුම", "සවරම් නැටුම", "පන්තේරු නැටුම", "නෛයන්ඩි නැටුම", "පොල් කටු එකට ගැටීමෙන් නැඟෙන හඬ තාලයට යොදා ගනිමින් පොල් කටු නැටුම නටයි."),
        q("පත්තිනි ඇදහිල්ල හා සම්බන්ධව අත් චාමර සලමින් ඉදිරිපත් කරන සාම්ප්‍රදායික නර්තන අංගය කුමක්ද?", "චාමර නැටුම", "කස නැටුම", "හේවිසි නැටුම", "කෝලම් නැටුම", "චාමර නැටුම දේව පූජා හා පෙරහැර අලංකාරය සඳහා යොදා ගන්නා ගෞරවනීය නැටුමකි."),
        q("සවරමක් හෙවත් මොනර පිල් හෝ සේද රෙදි බැඳි ආධාරකයක් අතින් ගෙන නටන ජනප්‍රිය නර්තන අංගය කුමක්ද?", "සවරම් නැටුම", "කළගෙඩි නැටුම", "ලී කෙළි නැටුම", "තෙල්මේ නැටුම", "සවරම් නැටුමේදී සවරම් යුගලය අත් දෙකෙන් කරකවමින් චමත්කාරජනක රටා මවයි."),
        q("ඇසළ පෙරහැරේ ආරම්භය සනිටුහන් කරමින් පෙරමුණේ ගමන් කරන විශේෂ කලා අංගය කුමක්ද?", "කසකරුවන් සහ ගිනිබෝල කරකවන්නන්", "සොකරි නළුවන්", "කෝලම් රජවරුන්", "රබන් කරකවන්නන්", "පෙරහැර මාර්ගය පිරිසිදු කරමින් පෙරහැරේ ආරම්භය දැනුම් දීම කසකරුවන්ගේ කාර්යයයි."),
        q("මහනුවර ඇසළ පෙරහැරේ අලි ඇතුන් ඉදිරියෙන් කොඩි සේසත් සමඟ ගමන් කරන ප්‍රධාන උඩරට නැටුම් කණ්ඩායම කුමක්ද?", "වෙස් නැටුම් කණ්ඩායම", "පූනා යාග කණ්ඩායම", "සොකරි කණ්ඩායම", "කෝලම් කණ්ඩායම", "දළදා කරඬුව වඩමවන ඇතු අභියස හෝ නිලමේවරුන් ඉදිරියේ වෙස් නැට්ටුවෝ නර්තනයේ යෙදෙති."),
        q("නර්තනය 'සංගීතය' යන පුළුල් කලා වර්ගීකරණයට ඇතුළත් වන බව දක්වන පැරණි ඉන්දීය ශාස්ත්‍රීය නියමය කුමක්ද?", "ගීතං වාද්‍යං තථා නෘත්‍යං ත්‍රයං සංගීත මුච්‍යතේ", "සාහිත්‍ය සංගීත කලා විහීනං", "නාට්‍ය වේදං චකාර ස:", "රසෝ වෛ ස:", "ගායනය, වාදනය සහ නර්තනය යන ත්‍රිත්වයම එක්ව සංගීතය ලෙස සංගීත රත්නාකරයේ දැක්වේ."),
        q("සාම්ප්‍රදායික නර්තනයේ සංශුද්ධතාව රැකගනිමින් අනාගත පරපුරට දායාද කිරීම හඳුන්වන්නේ කුමන කාර්යයක් ලෙසද?", "නර්තන කලා සංරක්ෂණය හා ප්‍රවර්ධනය", "නර්තන වාණිජකරණය", "නර්තන විනාශය", "නර්තන තහනම", "ගුරුකුල සම්ප්‍රදායන් හා ලිඛිත මූලාශ්‍ර සුරැකීම සංස්කෘතික උරුමය රැකගැනීමකි."),
        q("ලංකාවේ ප්‍රථම වරට වේදිකා නාට්‍යයකට සාම්ප්‍රදායික නර්තන අංග හා වෙස්මුහුණු සංයෝජනය කළ 'මනමේ' නාටකයේ නිර්මාතෘවරයා කවුද?", "මහාචාර්ය එදිරිවීර සරච්චන්ද්‍ර මහතා", "මහාචාර්ය සෙනරත් පරණවිතාන මහතා", "ඩී.බී. ධනපාල මහතා", "සිසිර සේනාරත්න මහතා", "1956 දී මහාචාර්ය සරච්චන්ද්‍රයන් නාඩගම් ආර හා දේශීය නර්තන ඇසුරෙන් මනමේ නිර්මාණය කළේය."),
        q("ශ්‍රී ලංකාවේ රාජ්‍ය නර්තන හා සෞන්දර්ය අධ්‍යාපනය වෙනුවෙන් පිහිටුවන ලද ප්‍රමුඛ විශ්වවිද්‍යාලය කුමක්ද?", "සෞන්දර්ය කලා විශ්වවිද්‍යාලය", "මොරටුව විශ්වවිද්‍යාලය", "වයඹ විශ්වවිද්‍යාලය", "ඌව වෙල්ලස්ස විශ්වවිද්‍යාලය", "හේවුඩ් ආයතනය පසුව සෞන්දර්ය කලා විශ්වවිද්‍යාලය බවට පත්ව නර්තන උපාධි පිරිනමයි."),
        q("පුරාණ ඉන්දීය විශ්වාස අනුව නර්තන කලාවේ මූලික නිර්මාතෘවරයා හෙවත් නටරාජ ලෙස සැලකෙන්නේ කුමන දෙවියාද?", "ශිව දෙවියන්", "ඉන්ද්‍ර දෙවියන්", "අග්නි දෙවියන්", "වරුණ දෙවියන්", "නටරාජ ස්වරූපයෙන් පෙනී සිටින ශිව දෙවියන් තාණ්ඩව නර්තනයේ නිර්මාතෘ ලෙස සැලකේ."),
        q("දේශීය නර්තනය 'අවිධිමත්' සිට 'විධිමත්' පාසල් අධ්‍යාපන ක්‍රමයකට මාරු වීම නිසා ඇති වූ ප්‍රධාන වාසිය කුමක්ද?", "සෑම සිසුවෙකුටම ශාස්ත්‍රීය පදනමකින් ඉගෙනීමට හැකි වීම", "ශාන්තිකර්ම සම්පූර්ණයෙන් අතුරුදන් වීම", "වෙස් ඇඳුම තහනම් වීම", "බෙර වාදනය නතර වීම", "කුල හෝ පවුල් පසුබිමකට සීමා නොවී ඕනෑම දරුවෙකුට නර්තනය හැදෑරීමට අවස්ථාව ලැබිණි."),
        q("දේශීය නර්තන ශිල්පියෙකු තම ගුරුවරයාගෙන් කලා ශිල්පය අධ්‍යයනය කොට ප්‍රසිද්ධියේ ආශිර්වාද ලබාගන්නා උත්සවය කුමක්ද?", "වෙස් මංගල්‍යය හෝ පායිම්පත් පැළඳවීම", "කම්මල් මංගල්‍යය", "අලුත් සහල් මංගල්‍යය", "නානුමුර මංගල්‍යය", "උඩරට නර්තනයේදී වෙස් මංගල්‍යයද සබරගමු හා පහතරට සම්ප්‍රදායේදී පායිම්පත් බැඳීමද පැවැත්වේ."),
        q("නර්තන ඉතිහාසයේදී 'පරංගි කාලය' හා ලන්දේසි යුගයන්හි බලපෑමෙන් මෙරටට එක් වූ සංගීත හා නර්තන අංගය කුමක්ද?", "බයිලා හා කපිරිඤ්ඤා", "උඩැක්කි නැටුම", "පන්තේරු නැටුම", "හංස වන්නම", "පෘතුගීසි හා අප්‍රිකානු සංස්කෘතික සම්මිශ්‍රණයෙන් කපිරිඤ්ඤා හා චිකෝටි නර්තන මෙරටට ලැබිණි."),
        q("පැරණි ලංකාවේ බෞද්ධ විහාරස්ථානවල දිනපතා පැවැත්වෙන හේවිසි පූජාවෙන් පිළිබිඹු වන සංස්කෘතික අර්ථය කුමක්ද?", "තෙරුවන් උදෙසා සිදු කරන ශබ්ද පූජාව", "කෘෂිකාර්මික බදු එකතු කිරීම", "රාජ්‍ය නීති ප්‍රකාශයට පත් කිරීම", "ගම් සභා රැස්වීම් ආරම්භ කිරීම", "දවුල, තම්මැට්ටම සහ හොරණෑව යොදා පවත්වන හේවිසි වාදනය ශ්‍රී ලාංකේය බෞද්ධ සම්ප්‍රදායේ අංගයකි."),
        q("උඩරට සම්ප්‍රදායේ විශිෂ්ට නර්තන ශිල්පියෙකු වූ නිට්ටවෙල ගුණයා මහතා ප්‍රකට වූයේ කුමන නැටුම් අංගයකින්ද?", "වෙස් නැටුම", "කෝලම් නැටුම", "සොකරි නැටුම", "කථක් නැටුම", "නිට්ටවෙල ගුණයා මහතා ලෝක ප්‍රකට උඩරට වෙස් නර්තන ශිල්පියෙකි."),
        q("ගාමිණී සහ මුද්‍රා නාට්‍ය ක්ෂේත්‍රයෙහි ලාංකේය නර්තන කලාව පෝෂණය කළ ප්‍රවීණ නර්තනවේදිනිය කවුද?", "වජිරා චිත්‍රසේන මහත්මිය", "රුක්මණී දේවි මහත්මිය", "මාලිනී ෆොන්සේකා මහත්මිය", "නන්දා මාලිනී මහත්මිය", "වජිරා චිත්‍රසේන මහත්මිය ශ්‍රී ලංකාවේ ප්‍රථම ප්‍රමුඛ බැලේ සහ මුද්‍රා නාට්‍ය ශිල්පිනියයි."),
        q("උඩරට නර්තන සම්ප්‍රදායේ කාන්තා නර්තනයට ගැළපෙන සේ නූතන කලායතනවල සකස් කර ඇති ප්‍රධාන ඇඳුම කුමක්ද?", "ඔසරිය හෝ නවීකරණය කළ උඩරට ලැසි ඇඳුම", "වෙස් තට්ටුව හා බඳ පටිය", "රතු තෙල්මේ තොප්පිය", "සන්නි වෙස්මුහුණ", "කාන්තාවන් වෙස් තට්ටුව නොපළඳින අතර ඊට අනුරූප ගෞරවනීය කාන්තා නර්තන ඇඳුම් භාවිත කරයි."),
        q("සිංහල ගැමි නාටක සම්ප්‍රදායන් අතර උඩරට සහ වන්නි ප්‍රදේශවල ප්‍රචලිත වූ ගැමි නාටක විශේෂය කුමක්ද?", "සොකරි", "කෝලම්", "රූකඩ", "පාස්කු", "ගුරුහාමි, සොකරි සහ පරයා වැනි චරිත ඇතුළත් සොකරි කමතේදී රඟ දැක්වේ."),
        q("සමූහ නර්තනයකදී ප්‍රේක්ෂකයාට ප්‍රසන්න දෘශ්‍ය අත්දැකීමක් ලබා දීමට වැදගත් වන ප්‍රධාන කරුණ කුමක්ද?", "සියලු ශිල්පීන්ගේ චලන එකමුතුව හා අංග රචන සමමිතිය", "එක් එක් ශිල්පියා වෙනස් තාලවලට නැටීම", "වේදිකාව අඳුරු කර තැබීම", "වාද්‍ය භාණ්ඩ ශබ්දය සම්පූර්ණයෙන් නැවැත්වීම", "සමූහ නර්තනයක සාර්ථකත්වය රඳා පවතින්නේ සමමිතිය, හැඩතල සහ ඒකාබද්ධ රිද්මය මතය."),
        q("යම් නර්තන සම්ප්‍රදායක අනන්‍යතාව හඳුනා ගැනීම සඳහා උපකාරී වන ප්‍රධානතම සාධක තුන මොනවාද?", "ප්‍රධාන බෙරය, නර්තන ඇඳුම සහ සාම්ප්‍රදායික ශාන්තිකර්ම", "වේදිකා ආලෝකකරණය, තිර රෙදි සහ පසුතල සැරසිලි", "සභා වන්දනාව, ආරාධිත කවි සහ පින් අනුමෝදනාව", "පෙරහුරු කාලසටහන, රංග ශාලාව සහ ප්‍රේක්ෂක ආසන", "එක් එක් සම්ප්‍රදායට ආවේණික බෙරය, ඇඳුම සහ ශාන්තිකර්ම මඟින් එහි අනන්‍යතාව ප්‍රකට කෙරේ."),
        q("මහනුවර පෙරහැරේ 'දිය කැපීමේ මංගල්‍යය' පැවැත්වීමෙන් සංකේතවත් කරන මූලික අරමුණ කුමක්ද?", "නිසි කලට වැසි ලැබී රට සශ්‍රීක වීම පැතීම", "නව යුද්ධයක් ප්‍රකාශ කිරීම", "පැරණි දේවාල නීති අහෝසි කිරීම", "නව වන්නම් කවි එළිදැක්වීම", "ගැටඹේ තොටේදී සිදු කරන දිය කැපීම කෘෂිකාර්මික සශ්‍රීකත්වය පතන සාම්ප්‍රදායික චාරිත්‍රයකි."),
        q("සම්ප්‍රදායික කලාකරුවන් විසින් නැටුම් පුහුණුව ආරම්භ කිරීමට පෙර බිමට අත තබා සිදු කරන චාරිත්‍රය කුමක්ද?", "මහී කාන්තාවගෙන් අවසර පැතීම හා නමස්කාර කිරීම", "වේදිකාව පිරිසිදු කිරීම", "පාවහන් ගලවා තැබීම", "වතුර පානය කිරීම", "පොළෝ මහී කාන්තාවට, ගුරුවරුන්ට හා බුදුන්ට වැඳ අවසර ගැනීම පෙරදිග නර්තන සම්ප්‍රදායකි."),
        q("ශ්‍රී ලංකාවේ පැරණි ගුරුකුල ක්‍රමයේදී නර්තනය ඉගැන්වීමේදී ගුරුවරයා හඳුන්වනු ලැබූ ගෞරවනීය නාමය කුමක්ද?", "ගුරුන්නාන්සේ හෝ යකැදුරුතුමා", "මුලාදෑනිතුමා", "විදානේ ආරච්චි", "කෝරාළතුමා", "පරම්පරා ගණනාවක් තිස්සේ ශිල්පය රැකගත් ආචාර්යවරුන් 'ගුරුන්නාන්සේ' ලෙස ගෞරවයෙන් හැඳින්විණි."),
        q("අනුරාධපුර රාජධානි සමයේ ඉදිකළ වාහල්කඩ හා කැටයම්වල දක්නට ලැබෙන නර්තනාංග හඳුන්වන්නේ කුමන නමකින්ද?", "වාමන රූප සහ ගාන්ධර්ව නර්තන රූප", "කෝලම් චරිත රූප", "බැලේ නළඟන රූප", "සබරගමු වන්නම් රූප", "කණ්ටක චේතිය ආදී ස්ථානවල වාමන රූප හා වාද්‍ය භාණ්ඩ සහිත කැටයම් පුරාණ කලාව පෙන්වයි."),
        q("උඩරට නර්තන සම්ප්‍රදායේ ආභාසය ලබමින් නිර්මාණය වූ 'පන්තේරු' නැටුමෙහි ඉතිහාසය සම්බන්ධ වන්නේ කුමන දේවියකටද?", "පත්තිනි දේවියගේ පාද සළඹට", "සරස්වතී දේවියගේ වීණාවට", "ලක්ෂ්මී දේවියගේ පද්මයට", "දුර්ගා දේවියගේ ආයුධයට", "පන්තේරුව පත්තිනි දේවියගේ සළඹ සංකේතවත් කරන බව ජනප්‍රවාදයේ සඳහන් වේ."),
        q("නර්තන ඉතිහාසයේදී 'පහතරට' සම්ප්‍රදායට අයත් ප්‍රධාන ගුරුකුල තුන හඳුන්වන්නේ කුමන නම්වලින්ද?", "මාතර, බෙන්තර සහ රයිගම ගුරුකුල", "මහනුවර, මාතලේ සහ කෑගල්ල ගුරුකුල", "යාපනය, මන්නාරම සහ මුලතිව් ගුරුකුල", "බදුල්ල, මොනරාගල සහ අම්පාර ගුරුකුල", "රයිගම, බෙන්තර සහ මාතර යනු පහතරට සම්ප්‍රදායේ සුවිශේෂී ප්‍රාදේශීය ගුරුකුල තුනය."),
        q("ශ්‍රී ලාංකේය ජන නැටුම් සංරක්ෂණය කර ගැනීම සඳහා පාසල් උත්සවවල ප්‍රධාන වශයෙන් පැවැත්වෙන ජාතික තරගාවලිය කුමක්ද?", "සමස්ත ලංකා නර්තන හා මුද්‍රා නාට්‍ය තරගාවලිය", "ජාතික මලල ක්‍රීඩා උළෙල", "අන්තර් පාසල් විවාද තරගාවලිය", "ජාතික විද්‍යා ප්‍රදර්ශනය", "අධ්‍යාපන අමාත්‍යාංශය මගින් සෑම වසරකම පාසල් නර්තන දක්ෂතා ඇගයීමට මෙම තරග පවත්වයි."),
        q("පැරණි සිංහල සමාජයේ නර්තනය හා සංගීතය ජනප්‍රිය වීමට බෙහෙවින් බලපෑ ප්‍රධාන සංස්කෘතික අංගය කුමක්ද?", "වෙහෙර විහාර හා දේවාල ආශ්‍රිත පූජා විධි", "නූතන සිනමා ශාලා ප්‍රසංග", "සංචාරක රංග ශාලා සංස්කෘතික සංදර්ශන", "ජාතික පාසල් ක්‍රීඩා සැණකෙළි", "විහාරස්ථාන හා දේවාලවල පැවති තේවා හා පෙරහැර චාරිත්‍ර නර්තනයේ ජීවනාලිය විය."),
        q("උඩරට නැටුමේ පුරාවෘත්තයට අනුව කොහොඹා කංකාරිය ඉගැන්වීමට ඉන්දියාවෙන් මෙරටට ගෙන්වන ලද රජු කවුද?", "මලය රජතුමා", "අශෝක රජතුමා", "කනිෂ්ක රජතුමා", "චන්ද්‍රගුප්ත රජතුමා", "ශක්‍ර දේවේන්ද්‍රයාගේ උපදෙස් පරිදි රාහුගේ මායාවෙන් මලය රජු හා සොහොයුරන් ලක්දිවට ගෙන්වූහ."),
        q("මලය රජු ලක්දිවට ගෙන්වා කොහොඹා කංකාරිය පැවැත්වූ ප්‍රථම ස්ථානය ලෙස ජනප්‍රවාදයේ සඳහන් වන්නේ කොහිද?", "හන්තාන හෙවත් උයන්වත්ත ප්‍රදේශය", "මන්නාරම වෙරළ තීරය", "ගාල්ල කොටු පවුර", "පුත්තලම කලපුව", "මහනුවර අනුරාධපුර මග ඔස්සේ පැමිණි මලය රජු හන්තානේදී කංකාරිය කළ බව සඳහන් වේ."),
        q("උඩරට නර්තන පරම්පරා අතර ප්‍රසිද්ධ 'නිත්තවෙල', 'අමුණුගම' හා 'තල්ගහගොඩ' යනු මොනවාද?", "සාම්ප්‍රදායික නර්තන ගුරුකුල හා පරම්පරා", "පැරණි වන්නම් කිහිපයක නම්", "බෙර වර්ග කිහිපයක නම්", "පහතරට සන්නි වෙස්මුහුණු නම්", "මධ්‍යම කඳුකරයේ ප්‍රදේශ නාම ඇසුරින් මෙම ප්‍රකට උඩරට නර්තන පරම්පරා බිහි විය."),
        q("පහතරට නර්තන ශිල්පීන්ගේ නර්තන පුහුණු ආයතන හා පරම්පරා පිහිටා ඇති ප්‍රසිද්ධ ප්‍රදේශයකට උදාහරණයක් කුමක්ද?", "අම්බලන්ගොඩ හා මාතර", "නුවරඑළිය හා බණ්ඩාරවෙල", "ත්‍රිකුණාමලය හා මඩකලපුව", "පොළොන්නරුව හා අනුරාධපුරය", "අම්බලන්ගොඩ පහතරට නැටුම් හා වෙස්මුහුණු කලාවේ ප්‍රධාන මධ්‍යස්ථානයකි."),
        q("දේශීය නර්තනය හා සම්බන්ධ 'වන්දනා කවි' සහ 'ආශිර්වාද කවි' ගායනා කිරීමේදී පවත්වා ගත යුතු විනය කුමක්ද?", "භක්තිය, ගෞරවය හා නිවැරදි උච්චාරණය", "හඬ නඟා හිනැහෙමින් ගැයීම", "තාලයට පටහැනිව ඉක්මනින් ගැයීම", "පිටුපස හරවාගෙන ගැයීම", "ශාන්තිකර්ම හා සම්ප්‍රදායික කවි ගායනයේදී වචන පැහැදිලි බව හා ගෞරවය අත්‍යවශ්‍ය වේ."),
        q("ශ්‍රී ලංකාවේ සම්ප්‍රදායික ජන නැටුම් ප්‍රධාන වශයෙන් නිරූපණය කරන්නේ කවර සමාජ ස්ථරයක ජීවිතයද?", "ග්‍රාමීය කෘෂිකාර්මික ජනතාවගේ ජීවිතය", "නාගරික කාර්මික ව්‍යාපාරික ජීවිතය", "රාජ සභාවේ විදේශ තානාපති ජීවිතය", "නූතන ක්‍රීඩා සමාජ ජීවිතය", "ගොවි ජනතාවගේ ශ්‍රමය, සතුට හා ආගමික විශ්වාස ජන නැටුම්වල පදනමයි."),
        q("පුරාණ ශ්‍රී ලංකාවේ නර්තනය පූජනීයත්වයෙන් සලකන ලද්දේ ඇයි?", "දෙවියන් පිදීම හා රෝග නිවාරණ ආශිර්වාද ලබාගැනීම නිසා", "රන් කාසි උපයන ක්‍රීඩාවක් වූ නිසා", "රාජ්‍ය සීමා ලකුණු කිරීමේ ක්‍රමයක් වූ නිසා", "හමුදා බලය පෙන්වීමේ අවියක් වූ නිසා", "ශාන්තිකර්ම හා දේව පූජාවන්හි මාධ්‍යයක් ලෙස නර්තනයට ගෞරවනීය ස්ථානයක් හිමි විය."),
        q("වත්මන් පාසල් විෂය මාලාව තුළ 'නර්තනය' විෂය ඇතුළත් කර ඇත්තේ කුමන විෂය ක්ෂේත්‍රය යටතේද?", "සෞන්දර්ය විෂය කාණ්ඩය යටතේ", "භාෂා හා සාහිත්‍ය විෂය කාණ්ඩය යටතේ", "ඉතිහාස හා පුරාවිද්‍යා විෂය කාණ්ඩය යටතේ", "පෙරදිග දර්ශන විෂය කාණ්ඩය යටතේ", "සංගීතය, චිත්‍ර හා නාට්‍ය කලාව සමඟ සෞන්දර්ය විෂය ධාරාවට නර්තනය අයත් වේ."),
        q("මහනුවර යුගයේ රචිත දහඅට වන්නම්වල මුල්ම කවි පදමාලා නිර්මාණය වීමට දායක වූයේ කවුරුන් බව සැලකේද?", "කවිකාර මඩුවේ කවීන් හා ගණිතාලංකාර ආචාර්යවරුන්", "පෘතුගීසි නාවික සෙනෙවිවරුන්", "ලන්දේසි ආණ්ඩුකාරවරුන්", "චීන සංචාරකයන්", "නරේන්ද්‍රසිංහ රජුගේ කවිකාර මඩුවේ සිටි උගතුන් වන්නම් කවි සකස් කිරීමට දායක විය."),
        q("සිංහල සංස්කෘතියේ කාන්තා ජන නැටුම් සඳහා ප්‍රධාන වශයෙන් යොදාගන්නා රිද්මයානුකූල උපකරණ දෙකක් මොනවාද?", "කළගෙඩි සහ අත් රබන්", "කඩු සහ පලිහ", "කස සහ ගිනිපන්දම්", "යක් බෙර සහ දවුල්", "කළගෙඩි, කුලු හා අත් රබන් ගැමි කාන්තාවන්ගේ ජන නැටුම්වල බහුලව භාවිත වේ."),
        q("පුරාණ ශ්‍රී ලංකාවේ බෞද්ධ සාහිත්‍යයේ සඳහන් 'නළඟනන්' යන්නෙන් අදහස් කරන්නේ කවුරුන්ද?", "නර්තන හා රංගන කලාවෙහි නිපුණ කාන්තාවන්", "මැටි බඳුන් නිපදවන ශිල්පිනියන්", "රෙදි වියන කාන්තාවන්", "සෙල්ලිපි කොටන කලාකරුවන්", "පැරණි සාහිත්‍යයේ නාට්‍ය හා ගීත රංගනයෙහි යෙදුණු කාන්තාවන් නළඟනන් ලෙස හැඳින්විණි."),
        q("උඩරට නර්තන සම්ප්‍රදාය හා බැඳුණු පැරණි පුස්කොළ පොත්වල ප්‍රධාන වශයෙන් සටහන් කර තිබුණේ මොනවාද?", "කවි, ශ්ලෝක, තාල පද හා ශාන්තිකර්ම විධි", "විදේශීය නාට්‍ය පිටපත් හා සංගීත සටහන්", "පැරණි රාජ්‍ය ආඥා පනත් හා ලේඛන", "වෙස්මුහුණු කැපීමේ මිනුම් හා සටහන් පමණි", "පරම්පරාගතව පැවත ආ නැටුම් පද, කංකාරි පිළිවෙත් හා මන්ත්‍ර පුස්කොළ පොත්වල ලියැවිණි."),
        q("නර්තන කලාවේදී 'ගුරු ගෝල සම්ප්‍රදාය' යන්නෙන් අදහස් කරන්නේ කුමක්ද?", "ගුරුවරයා වෙතින් සෘජුවම ප්‍රායෝගිකව ශිල්පය ප්‍රගුණ කිරීම", "පොත්පත් කියවා තනිවම නැටුම් පියවර ඉගෙනීම", "ලිඛිත විභාග ප්‍රශ්න පත්‍ර පමණක් පිළියෙළ කිරීම", "වේදිකාවේ ආලෝක උපකරණ පමණක් හැසිරවීම", "ශාස්ත්‍රීය නර්තනයේ නිවැරදි අංගහාර හා ආකල්ප ලැබෙන්නේ ගුරු ඇසුරෙනි."),
        q("සම්ප්‍රදායික නැටුම් ශිල්පීන් පූජා භූමිවලදී පාවහන් නොපැළඳ නර්තනයේ යෙදෙන්නේ ඇයි?", "පොළොවට හා පූජනීය ස්ථානයට දක්වන ගෞරවය නිසා", "පාවහන් මිල අධික නිසා", "වේගයෙන් ධාවනය කිරීමට පහසු නිසා", "නවීන විලාසිතාවක් නිසා", "පාවහන් ඉවත් කර නැටීම දේව ගෞරවය හා බිම් සමතුලිතතාව සඳහා වැදගත් වේ."),
        q("පෙරහැර කලාවේදී 'ගින්නෙන් හා දුමින්' සිදු කරන ආරක්ෂක හා සෞන්දර්ය අංගය නියෝජනය කරන්නේ කවුද?", "පන්දම්කරුවන් සහ ගිනිබෝල කරකවන්නන්", "හක්ගෙඩි පිඹින්නන්", "මුතුකුඩ අල්ලන්නන්", "කළගෙඩි නටන්නියන්", "රාත්‍රී පෙරහැරට ආලෝකය හා තේජස එක් කිරීම පන්දම් හා ගිනිබෝල ශිල්පීන්ගෙන් සිදු වේ."),
        q("ශ්‍රී ලංකාවේ නර්තන උරුමය ජාත්‍යන්තර වශයෙන් ප්‍රචලිත වීමට ඉවහල් වූ ප්‍රධාන සාංස්කෘතික සංදර්ශනය කුමක්ද?", "මහනුවර ඇසළ පෙරහැර", "සිංහල අලුත් අවුරුදු ක්‍රීඩා", "කතරගම පාද යාත්‍රාව", "පොසොන් පහන් කූඩු ප්‍රදර්ශනය", "ලොව පුරා සංචාරකයන් ආකර්ෂණය කරගන්නා මහනුවර පෙරහැර දේශීය නර්තන කලාවේ කැඩපතකි."),
        q("උඩරට, පහතරට හා සබරගමු නර්තන අතර පොදු වශයෙන් දක්නට ලැබෙන මූලික ලක්ෂණය කුමක්ද?", "සියලු සම්ප්‍රදායන් ශාන්තිකර්ම හා පූජා විධි ඇසුරෙන් බිහිවීම", "සියල්ලටම එකම වෙස් තට්ටුව පැළඳීම", "සියල්ලටම යක් බෙරය පමණක් වැයීම", "සියල්ලම විදේශීය භාෂාවලින් ගැයීම", "ත්‍රිවිධ සම්ප්‍රදායන්හිම මූලික පදනම දේශීය යාතුකර්ම හා ශාන්තිකර්මයි."),
        q("පැරණි ලංකාවේ කුල ක්‍රමය අනුව නර්තන හා බෙර වාදන ශිල්පීන් හැඳින්වීමට භාවිත කළ ගෞරවනීය නාමයක් කුමක්ද?", "පණික්කිල හෝ පණිවිඩකාර ශිල්පීන්", "මහ අදිකාරම්", "දිසාවේ නිලමේ", "බස්නායක නිලමේ", "ගම් සභා හා රාජකාරි සේවාවන්හි නියැලි කලා ශිල්පීන්ට විවිධ ප්‍රාදේශීය නාම භාවිත විය."),
        q("පැරණි සිංහල රජවරුන් විසින් නර්තන කණ්ඩායම් පවත්වාගෙන ගිය ප්‍රධාන රාජ්‍ය උත්සවය කුමක්ද?", "රාජාභිෂේකය හා සතර මහා මංගල්‍යයන්", "ග්‍රාමීය සිංහල අවුරුදු ජන ක්‍රීඩා", "වෙරළබඩ ධීවර කර්මාන්ත උත්සව", "රාත්‍රී ගැමි සොකරි කමත් රංගන", "අලුත් සහල්, අවුරුදු, ඇසළ හා කාර්තික මංගල්‍යයන්හිදී රාජකීය නර්තන පැවැත්විණි."),
        q("නර්තන විෂය හැදෑරීමෙන් සිසුවෙකු තුළ වර්ධනය වන ප්‍රධාන සමාජීය ගුණාංගය කුමක්ද?", "සමූහ හැඟීම, විනය හා සංස්කෘතික ගරුත්වය", "හුදකලා බව හා ආත්මාර්ථකාමිත්වය", "අනෙක් කලාවන් ප්‍රතික්ෂේප කිරීම", "අවිනීත හැසිරීම", "නර්තන කණ්ඩායමක එකට වැඩ කිරීමෙන් සහයෝගීතාව හා සංයමය දියුණු වේ."),
        q("වේදිකා නර්තන නිර්මාණයකදී පැරණි ගැමි ජන ගී හා නැටුම් නැවත සකස් කිරීම හඳුන්වන්නේ කෙසේද?", "වේදිකා අනුවර්තනය හෙවත් සාම්ප්‍රදායික ප්‍රතිනිර්මාණය", "ශාන්තිකර්ම අත්හැරීම", "බටහිර අනුකරණය", "සම්ප්‍රදාය විකෘති කිරීම", "සාම්ප්‍රදායික ජීව ගුණය රැකගෙන නූතන වේදිකාවට සුදුසු ලෙස සැකසීම වැදගත් වේ."),
        q("ශ්‍රී ලංකාවේ නර්තන ඉතිහාසයේදී 'පහතරට' හා 'උඩරට' නැටුම් එකිනෙකින් වෙනස් වීමට බලපෑ ප්‍රධාන සාධකය කුමක්ද?", "භූගෝලීය පරිසරය, භාෂා ව්‍යවහාරය හා දේශීය ඇදහිලි", "නවීන පාසල් නිල ඇඳුම්", "විද්‍යුත් ශබ්ද විකාශන යන්ත්‍ර", "පාසල් නිවාඩු කාලසටහන", "කඳුකර හා වෙරළබඩ සමාජ පරිසරයන් අනුව තාල රටා, ඇඳුම් හා භාෂාව විවිධත්වයට පත්විය."),
        q("නර්තනය 'සංවේදී හා සෞන්දර්යාත්මක කලාවක්' ලෙස හඳුන්වන්නේ ඇයි?", "මිනිස් භාවයන් රිද්මයානුකූල චලන මගින් ප්‍රකාශ කරන බැවිනි", "තාල අංක සටහන් පමණක් කටපාඩම් කරන බැවිනි", "පද විස්තර ලිඛිතව කියවීම පමණක් සිදු කරන බැවිනි", "වේදිකා උපකරණ තැනීම පමණක් ඉගැන්වෙන බැවිනි", "ශාරීරික චලන, සංගීතය හා අභිනය මගින් හදවතට දැනෙන රසයක් උපදවයි."),
        q("පැරණි දේවාල නර්තන කලාවෙහි දේව පූජා උදෙසා නටන ලද කාන්තා නැටුම් හඳුන්වනු ලැබූයේ කෙසේද?", "දිග්ගේ නැටුම්", "රබන් නැටුම්", "කළගෙඩි නැටුම්", "සන්නි නැටුම්", "සබරගමුව හා පැරණි දේවාලවල දිග්ගේ නමැති මණ්ඩපයේ කාන්තාවන් විසින් පූජා නැටුම් ඉදිරිපත් කරන ලදී."),
        q("උඩරට නැටුමේ පූර්ණ කලා ශිල්පියෙකු වීමට පෙර අවසන් කළ යුතු ප්‍රධාන පුහුණු අදියර කුමක්ද?", "සරඹ පුහුණුව හා වන්නම් ප්‍රගුණ කිරීම", "කෝලම් කැපීම ඉගෙනීම", "බැලේ පාවහන් පැළඳීම", "වයලීන් වාදනය ඉගෙනීම", "පා සරඹ හා ගොඩ සරඹ මනාව ප්‍රගුණ කිරීමෙන් පසුව වන්නම් හා වෙස් නැටුමට යොමු කෙරේ."),
        q("ලංකාවේ නර්තන ක්ෂේත්‍රයේ පළමු පෙළේ විද්වත් ග්‍රන්ථයක් වන 'උඩරට නැටුම් කලාව' ග්‍රන්ථය රචනා කළේ කවුද?", "ජේ.ඊ. සේදරමන් මහතා", "ඩබ්ලිව්.ඒ. සිල්වා මහතා", "ජී.බී. සේනානායක මහතා", "මඩවල එස්. රත්නායක මහතා", "ජේ.ඊ. සේදරමන් මහතා උඩරට නැටුම් හා කංකාරි පිළිබඳ වටිනා පර්යේෂණ ග්‍රන්ථ රැසක් ලියූහ."),
        q("උඩරට හා පහතරට නර්තන සම්ප්‍රදායන් දෙකෙහිම භාවිත වන පොදු අලංකාර චලන අංගයක් කුමක්ද?", "මණ්ඩි ඉරියව්ව සහ කැරකිලි", "වෙස්මුහුණු ගලවා දැමීම", "අයිස් මත ලිස්සා යාම", "කඩු සටන් කිරීම", "දෙපා නමා තබන මණ්ඩි ඉරියව්ව දේශීය නර්තන සම්ප්‍රදායන්හි පදනමයි."),
        q("සිංහල ජන ක්‍රීඩා හා ජන නැටුම් බහුලව පවත්වනු ලබන ප්‍රධාන ජාතික සංස්කෘතික උළෙල කුමක්ද?", "සිංහල හා දෙමළ අලුත් අවුරුදු උළෙල", "වෙසක් පොහොය උළෙල", "පොසොන් පොහොය උළෙල", "කඨින පූජා උළෙල", "බක් මාසයේ අලුත් අවුරුදු සමයේ රබන් ක්‍රීඩා හා ජන නැටුම් ගම් දනව් පුරා පැවැත්වේ."),
        q("දේශීය නර්තනයේදී ගායනා කරන පැරණි කවිවල භාෂා ශෛලිය හා එළිසමය මගින් ඉටු වන කාර්යය කුමක්ද?", "නැටුමේ රිද්මය හා තාලය පවත්වා ගැනීමට උපකාරී වීම", "ශිල්පීන්ගේ නින්ද නැති කිරීම", "ප්‍රේක්ෂකයන් බිය ගැන්වීම", "බෙර වාදනය අවලංගු කිරීම", "ගායනා කරන කවිවල මාත්‍රා හා විරිත නර්තන පියවර සමඟ මනාව බද්ධ වේ."),
        q("ශ්‍රී ලංකාවේ නර්තන සම්ප්‍රදායන් ලෝක සංස්කෘතික උරුමයන් අතර සුවිශේෂී වීමට හේතුව කුමක්ද?", "දේශීය ශාන්තිකර්ම, අනන්‍ය වාද්‍ය භාණ්ඩ හා ස්වභාවික රිද්මයන්", "සම්පූර්ණයෙන්ම යුරෝපීය ආකෘති අනුගමනය කිරීම", "වාද්‍ය භාණ්ඩ කිසිවක් භාවිත නොකිරීම", "සජීවී නර්තන නොමැති වීම", "සියවස් ගණනාවක් පැරණි කලාත්මක ලක්ෂණ නොනැසී පැවතීම මෙහි විශේෂත්වයයි."),
        q("නර්තන කලාවේදී 'ගුරු පූජාව' පැවැත්වීමෙන් ශිෂ්‍යයා තුළ ඇති වන ප්‍රධාන ගුණාංගය කුමක්ද?", "කෘතඥතාව හා කලා විනය", "උඩඟුකම හා අහංකාරය", "ප්‍රතිවාදීන්ට වෛර කිරීම", "ශිල්පය සඟවා තැබීම", "බුලත් හුරුල්ලක් දී ගුරුවරයාට වැඳ නමස්කාර කිරීමෙන් කලාව කෙරෙහි ගෞරවය වැඩේ."),
        q("සිංහල නාඩගම් කලාවෙන් පෝෂණය වී නූතන වේදිකාවට නර්තනමය නාට්‍ය ආකෘතියක් ගෙන ආ කලා ශෛලිය කුමක්ද?", "ශෛලිගත නාට්‍ය සම්ප්‍රදාය", "තාත්වික නාට්‍ය සම්ප්‍රදාය", "විකට නාට්‍ය සම්ප්‍රදාය", "පරිවර්තන නාට්‍ය සම්ප්‍රදාය", "ගීත, වාදන හා රිද්මයානුකූල නර්තන චලන එක්වුණු ශෛලිගත නාට්‍ය සම්ප්‍රදාය ලංකාවේ බිහි විය."),
        q("නර්තනය හා සම්බන්ධ 'තූර්ය වාදන' යන පදයෙන් අදහස් කෙරෙන්නේ කුමක්ද?", "පංචතූර්ය වාද්‍ය භාණ්ඩ වාදනය කිරීම", "වචන උච්චාරණය කිරීම පමණි", "වේදිකා තිර සැරසීම", "රංග වස්ත්‍ර මැසීම", "නර්තනයට පසුබිම් රිද්මය සපයන සියලු වාද්‍ය භාණ්ඩ වාදනය තූර්ය වාදනයට අයත් වේ."),
        q("උඩරට නැටුම් පුහුණුවීමේදී ශිෂ්‍යයන්ගේ දෑත් හා පාද ශක්තිමත් කිරීමට පිහිටුවා ගන්නා ලී පොල්ල කුමක්ද?", "දණ්ඩියම් කඳ", "හරස් පුවරුව", "තාලම් ලීය", "කඩු මිට", "පොළොව මත ආධාරක දෙකක් මත සවි කළ දණ්ඩියම අල්ලාගෙන මූලික පා සරඹ පුහුණු වේ."),
        q("උඩරට සම්ප්‍රදායේ 'වෙස්' නැටුමෙන් වෙනස්ව සැහැල්ලු ඇඳුමකින් හා අඩු ආභරණවලින් නටන නැටුම කුමක්ද?", "නෛයන්ඩි නැටුම", "කෝලම් නැටුම", "සොකරි නැටුම", "තෙල්මේ නැටුම", "වෙස් බැඳීමට පෙර සුදු උඩුකය ආවරණයක් හෝ නැතිව සිළම්බු හා රෙද්ද පැළඳ නෛයන්ඩි නටයි."),
        q("දේශීය නර්තන සම්ප්‍රදායන්හිදී නැට්ටුවන්ගේ දෙපාවල බඳිනු ලබන ශබ්ද උපදවන පළඳනාව කුමක්ද?", "සිළම්බු හෝ ගෙජ්ජි", "අවුල්හැරය", "කරපටිය", "හංස පූට්ටුව", "නැටුමේ පාද තැබීම අනුව මිහිරි නාදයක් ලබා දීමට වළලුකරේ සිළම්බු හෝ ගෙජ්ජි පළඳියි."),
        q("ශ්‍රී ලංකාවේ සාම්ප්‍රදායික නර්තන හදාරන සිසුන් සඳහා ප්‍රසිද්ධ 'කලඑළි මංගල්‍යය' යනු කුමක්ද?", "නවක ශිෂ්‍යයෙකු ප්‍රථම වරට ප්‍රේක්ෂකයන් ඉදිරියේ රංගනය ඉදිරිපත් කිරීම", "පැරණි හේවිසි හා ගැටබෙර අලුත්වැඩියා කර හම් ගැසීමේ චාරිත්‍රය", "පාරම්පරික නැටුම් කලායතනය වසා දමා සමුගැනීමේ විශේෂ උත්සවය", "රංග වස්ත්‍ර හා සිළම්බු සියල්ල ප්‍රදර්ශනයට තබා ආශිර්වාද ගැනීම", "මූලික පුහුණුව අවසන් කළ ශිෂ්‍යයා ගුරු ආශිර්වාදය මැද කලඑළි බැසීම මෙයින් සිදු වේ.")
    )
}
